 	if flags.RecordBaseline != "" {
-		return writeVerifyBaseline(ctx, opts, repo, flags, results, parser, parsed, exitCode)
+		return writeVerifyBaseline(ctx, opts, repo, flags, policy.Digest, before, results, parser, parsed, exitCode)
