-	results verifyResults, parser string, parsed bool, exitCode int,
+	policyDigest string, before verifyTree, results verifyResults, parser string, parsed bool, exitCode int,
 ) error {
 	baseline := verifyBaseline{
 		FormatVersion: 1,
 		RecordedAt:    time.Now().UTC().Format(time.RFC3339),
 		Repo:          repo,
+		Scope:         flags.Scope,
+		SetupCommand:  flags.Setup,
+		PolicyDigest:  policyDigest,
+		Platform:      runtime.GOOS + "/" + runtime.GOARCH,
+		TimeoutMillis: verifyTimeout(flags.Test).Milliseconds(),
 		TestCommand:   flags.Test,
 		Parser:        parser,
 		ExitCode:      exitCode,
 		Results:       results,
 	}
+	after := captureVerifyTree(ctx, repo, flags.RecordBaseline)
+	baseline.Commit, baseline.Tree = before.commit, before.tree
+	baseline.CleanTree = before.clean && after.clean && before.commit == after.commit && before.tree == after.tree
+	if set, err := intent.Load(repo); err == nil {
+		baseline.IntentDigest = set.Digest
+	}
 	if !parsed {
 		baseline.Parser = "exit-code-only"
 		baseline.Results = verifyResults{}
@@ -254,6 +302,13 @@ func writeVerifyBaseline(
 	return nil
 }

+func verifyTimeout(command string) time.Duration {
+	if verifyCompiledCommand(command) {
+		return verifyCompiledTimeout
+	}
+	return verifyInterpretedTimeout
+}
+
 func readVerifyBaseline(path string) (verifyBaseline, error) {
 	content, err := os.ReadFile(path)
 	if err != nil {
@@ -407,3 +462,45 @@ func verifyTruncateOutput(rendered string, maxBytes int) []byte {
 	}
 	return []byte(strings.Join(append(kept, verdict), "\n"))
 }
+
+// A baseline can certify a committed view only when the checkout was clean
+// both before and after execution. Dirty baselines still support verify deltas.
+type verifyTree struct {
+	commit, tree string
+	clean        bool
+}
+
+func captureVerifyTree(ctx context.Context, repo, evidencePath string) verifyTree {
+	commit, tree, err := gitutil.HeadCommitAndTree(ctx, repo)
+	if err != nil {
+		return verifyTree{}
+	}
+	state := verifyTree{commit: commit, tree: tree}
+	// HEAD comparison includes both staged and unstaged changes. Never exclude
+	// a tracked evidence file, since its contents are part of the selected tree.
+	cmd := exec.CommandContext(ctx, "git", "-C", repo, "diff", "--quiet", "--no-ext-diff", "--ignore-submodules=none", "HEAD", "--")
+	if err := cmd.Run(); err != nil {
+		return state
+	}
+	cmd = exec.CommandContext(ctx, "git", "-C", repo, "ls-files", "--others", "--exclude-standard", "-z")
+	output, err := cmd.Output()
+	if err != nil {
+		return state
+	}
+	evidence, err := filepath.Abs(evidencePath)
+	if err != nil {
+		return state
+	}
+	evidence, _ = filepath.EvalSymlinks(evidence)
+	for _, path := range strings.Split(string(output), "\x00") {
+		if path == "" {
+			continue
+		}
+		candidate, err := filepath.EvalSymlinks(filepath.Join(repo, path))
+		if err != nil || evidencePath == "" || candidate != evidence {
+			return state
+		}
+	}
+	state.clean = true
+	return state
+}
diff --git a/internal/cli/verify_test.go b/internal/cli/verify_test.go
index 4a2be1a5..beecc720 100644
--- a/internal/cli/verify_test.go
+++ b/internal/cli/verify_test.go
@@ -2,6 +2,7 @@ package cli

 import (
 	"bytes"
+	"encoding/json"
 	"os"
 	"path/filepath"
 	"strings"
@@ -313,3 +314,31 @@ func TestParseVerifyFlagsRequiresABaseline(t *testing.T) {
 		t.Fatal("timeout ecosystem split is wrong")
 	}
 }
+
+func TestVerifyPolicyPersistsDigestAndRejectsChangedPolicy(t *testing.T) {
+	repo := t.TempDir()
+	write(t, repo, ".entire/graph/verification.yaml", "version: 1\nscopes:\n  - id: unit\n    command: sh run.sh\n")
+	write(t, repo, "run.sh", "#!/bin/sh\necho 'tests/test_a.py::test_target PASSED'\n")
+	if err := os.Chmod(filepath.Join(repo, "run.sh"), 0o755); err != nil {
+		t.Fatal(err)
+	}
+	baselinePath := filepath.Join(t.TempDir(), "baseline.json")
+	run := func(args ...string) error {
+		return Run(t.Context(), Options{Version: "0.1.0", Env: EntireEnv{RepoRoot: repo}, Stdout: &bytes.Buffer{}}, append([]string{"verify", "--repo", repo, "--test", "sh run.sh", "--scope", "unit"}, args...))
+	}
+	if err := run("--record-baseline", baselinePath); err != nil {
+		t.Fatal(err)
+	}
+	content, err := os.ReadFile(baselinePath)
+	if err != nil {
+		t.Fatal(err)
+	}
+	var baseline verifyBaseline
+	if err := json.Unmarshal(content, &baseline); err != nil || baseline.PolicyDigest == "" || baseline.FormatVersion != 1 {
+		t.Fatalf("baseline = %#v err = %v", baseline, err)
+	}
+	write(t, repo, ".entire/graph/verification.yaml", "version: 1\nscopes:\n  - id: unit\n    command: sh run.sh\n  - id: integration\n    command: sh integration.sh\n")
+	if err := run("--pre-edit-baseline", baselinePath); err == nil || !strings.Contains(err.Error(), "policy digest") {
+		t.Fatalf("changed policy error = %v", err)
+	}
+}

